static void command_release(document_edit *edit, document_edit_command *command)
{
    document_edit_blob_release(edit, command->before);
    document_edit_blob_release(edit, command->after);
    memset(command, 0, sizeof(*command));
}

static void clear_redo(document_edit *edit)
{
    for (size_t i = edit->command_cursor; i < edit->command_count; ++i)
        command_release(edit, &edit->commands[i]);
    edit->command_count = edit->command_cursor;
}

static bool reserve_commands(document_edit *edit)
{
    if (edit->command_count < edit->command_capacity) return true;
    if (edit->command_count == edit->limits.history_commands &&
        edit->command_capacity == edit->limits.history_commands) return true;
    size_t next = edit->command_capacity == 0U ? 8U : edit->command_capacity * 2U;
    if (next > edit->limits.history_commands) next = edit->limits.history_commands;
    if (next <= edit->command_capacity || next > SIZE_MAX / sizeof(*edit->commands))
        return false;
    document_edit_command *commands = realloc(edit->commands,
                                               next * sizeof(*edit->commands));
    if (commands == NULL) return false;
    memset(commands + edit->command_capacity, 0,
           (next - edit->command_capacity) * sizeof(*commands));
    edit->commands = commands;
    edit->command_capacity = next;
    return true;
}

static void drop_oldest_command(document_edit *edit)
{
    if (edit->command_count == 0U) return;
    command_release(edit, &edit->commands[0]);
    if (edit->command_count > 1U)
        memmove(edit->commands, edit->commands + 1U,
                (edit->command_count - 1U) * sizeof(*edit->commands));
    --edit->command_count;
    if (edit->command_cursor > 0U) --edit->command_cursor;
    memset(&edit->commands[edit->command_count], 0, sizeof(*edit->commands));
}

static bool make_piece_copy(document_edit *edit, size_t offset, size_t length,
                            uint8_t **out_bytes)
{
    uint8_t *bytes = length == 0U ? NULL : malloc(length);
    if (length > 0U && bytes == NULL) return false;
    if (length > 0U && !document_edit_read_range(edit, offset, length, bytes)) {
        free(bytes);
        return false;
    }
    *out_bytes = bytes;
    return true;
}

document_edit_error document_edit_commit_replace(document_edit *edit,
    size_t offset, size_t remove_length, const uint8_t *insert, size_t insert_length,
    uint32_t target_slot, bool coalescible_attribute,
    document_edit_history_action action)
{
    base_bytes label = document_edit_history_action_label(action);
    if (edit == NULL || (insert_length > 0U && insert == NULL) ||
        !base_bytes_valid(label) || label.len == 0U ||
        label.len >= DOCUMENT_EDIT_HISTORY_LABEL_CAP ||
        offset > edit->byte_length || remove_length > edit->byte_length - offset)
        return DOCUMENT_EDIT_INVALID_ARGUMENT;
    size_t next_length = edit->byte_length - remove_length;
    svg_xml_options xml_options = svg_xml_default_options();
    if (!base_size_add(next_length, insert_length, &next_length) ||
        next_length > xml_options.limits.input_bytes) return DOCUMENT_EDIT_LIMIT;
    if (edit->next_state_id == UINT64_MAX) return DOCUMENT_EDIT_LIMIT;
    if (remove_length == insert_length) {
        uint8_t *existing = NULL;
        if (!make_piece_copy(edit, offset, remove_length, &existing))
            return DOCUMENT_EDIT_OUT_OF_MEMORY;
        bool same = remove_length == 0U || memcmp(existing, insert, remove_length) == 0;
        free(existing);
        if (same) return DOCUMENT_EDIT_OK;
    }

    bool coalesce = coalescible_attribute && edit->command_cursor == edit->command_count &&
        edit->command_count > 0U &&
        edit->saved_state_id != edit->state_id &&
        edit->commands[edit->command_count - 1U].coalescible_attribute &&
        edit->commands[edit->command_count - 1U].target_slot == target_slot &&
        edit->commands[edit->command_count - 1U].offset == offset;
    uint8_t *before_bytes = NULL;
    if (!make_piece_copy(edit, offset, remove_length, &before_bytes))
        return DOCUMENT_EDIT_OUT_OF_MEMORY;
    document_edit_error blob_error = DOCUMENT_EDIT_OK;
    document_edit_blob *before = coalesce ? NULL : document_edit_blob_create(
        edit, before_bytes, remove_length, &blob_error);
    free(before_bytes);
    if (!coalesce && remove_length > 0U && before == NULL) return blob_error;
    document_edit_blob *after = document_edit_blob_create(edit, insert, insert_length,
                                                          &blob_error);
    if (insert_length > 0U && after == NULL) {
        document_edit_blob_release(edit, before);
        return blob_error;
    }

    document_edit_piece *pieces = NULL;
    size_t piece_count = 0U, piece_capacity = 0U, byte_length = 0U;
    if (!piece_table_replace_copy(edit, offset, remove_length, after, &pieces,
                                  &piece_count, &piece_capacity, &byte_length)) {
        document_edit_blob_release(edit, before);
        document_edit_blob_release(edit, after);
        return DOCUMENT_EDIT_OUT_OF_MEMORY;
    }
    if (!coalesce && edit->command_count < edit->limits.history_commands &&
        !reserve_commands(edit)) {
        release_pieces(edit, pieces, piece_count);
        document_edit_blob_release(edit, before);
        document_edit_blob_release(edit, after);
        return DOCUMENT_EDIT_OUT_OF_MEMORY;
    }

    clear_redo(edit);
    uint64_t new_state = edit->next_state_id++;
    if (coalesce) {
        document_edit_command *previous = &edit->commands[edit->command_count - 1U];
        document_edit_blob_release(edit, previous->after);
        previous->after = after;
        previous->after_state = new_state;
        memcpy(previous->label, label.ptr, label.len);
        previous->label[label.len] = '\0';
    } else {
        if (edit->command_count == edit->limits.history_commands) drop_oldest_command(edit);
        document_edit_command command = {.offset = offset, .before = before,
            .after = after, .target_slot = target_slot,
            .coalescible_attribute = coalescible_attribute,
            .before_state = edit->state_id, .after_state = new_state};
        memcpy(command.label, label.ptr, label.len);
        command.label[label.len] = '\0';
        edit->commands[edit->command_count++] = command;
        edit->command_cursor = edit->command_count;
    }
    release_pieces(edit, edit->pieces, edit->piece_count);
    edit->pieces = pieces;
    edit->piece_count = piece_count;
    edit->piece_capacity = piece_capacity;
    edit->byte_length = byte_length;
    edit->state_id = new_state;
    document_edit_invalidate_index(edit);
    return DOCUMENT_EDIT_OK;
}

document_edit_error document_edit_undo(document_edit *edit)
{
    if (edit == NULL) return DOCUMENT_EDIT_INVALID_ARGUMENT;
    if (edit->command_cursor == 0U) return DOCUMENT_EDIT_INVALID_OPERATION;
    document_edit_command *command = &edit->commands[edit->command_cursor - 1U];
    size_t after_length = command->after == NULL ? 0U : command->after->length;
    size_t before_length = command->before == NULL ? 0U : command->before->length;
    if (!document_edit_validate_replace(edit, 0U, edit->byte_length,
            command->offset, after_length,
            command->before == NULL ? NULL : command->before->bytes,
            before_length, false, false)) return DOCUMENT_EDIT_MALFORMED_XML;
    if (!document_edit_replace_raw(edit, command->offset, after_length, command->before))
        return DOCUMENT_EDIT_OUT_OF_MEMORY;
    --edit->command_cursor;
    edit->state_id = command->before_state;
    document_edit_invalidate_index(edit);
    return DOCUMENT_EDIT_OK;
}

document_edit_error document_edit_redo(document_edit *edit)
{
    if (edit == NULL) return DOCUMENT_EDIT_INVALID_ARGUMENT;
    if (edit->command_cursor >= edit->command_count) return DOCUMENT_EDIT_INVALID_OPERATION;
    document_edit_command *command = &edit->commands[edit->command_cursor];
    size_t before_length = command->before == NULL ? 0U : command->before->length;
    size_t after_length = command->after == NULL ? 0U : command->after->length;
    if (!document_edit_validate_replace(edit, 0U, edit->byte_length,
            command->offset, before_length,
            command->after == NULL ? NULL : command->after->bytes,
            after_length, false, false)) return DOCUMENT_EDIT_MALFORMED_XML;
    if (!document_edit_replace_raw(edit, command->offset, before_length, command->after))
        return DOCUMENT_EDIT_OUT_OF_MEMORY;
    ++edit->command_cursor;
    edit->state_id = command->after_state;
    document_edit_invalidate_index(edit);
    return DOCUMENT_EDIT_OK;
}

size_t document_edit_byte_length(const document_edit *edit)
{
    return edit == NULL ? 0U : edit->byte_length;
}

bool document_edit_materialize(const document_edit *edit, uint8_t *buffer,
                               size_t capacity, size_t *out_length)
{
    if (edit == NULL || out_length == NULL ||
        (capacity > 0U && buffer == NULL)) return false;
    *out_length = edit->byte_length;
    if (capacity < edit->byte_length) return false;
    return document_edit_read_range(edit, 0U, edit->byte_length, buffer);
}

bool document_edit_is_dirty(const document_edit *edit)
{
    return edit != NULL && edit->state_id != edit->saved_state_id;
}

size_t document_edit_history_count(const document_edit *edit)
{
    return edit == NULL ? 0U : edit->command_count;
}

size_t document_edit_history_cursor(const document_edit *edit)
{
    return edit == NULL ? 0U : edit->command_cursor;
}

void document_edit_piece_table_destroy(document_edit *edit)
{
    if (edit == NULL) return;
    release_pieces(edit, edit->pieces, edit->piece_count);
    edit->pieces = NULL;
    edit->piece_count = 0U;
    for (size_t i = 0U; i < edit->command_count; ++i)
        command_release(edit, &edit->commands[i]);
    free(edit->commands);
    edit->commands = NULL;
    edit->command_count = 0U;
}
use crate::{alloc, cache::Cache, *};
use vexel_document::DocumentHandle;
impl Editor {
    pub fn set_attribute(
        &mut self,
        node: DocumentHandle,
        name: &[u8],
        value: &[u8],
    ) -> Result<(), EditError> {
        checked_name(name)?;
        let cache = self.handle_index(node)?;
        let info = cache.node(node)?;
        let Some(attr) = cache.attribute(info, name) else {
            return self.add_attribute(node, name, value);
        };
        let encoded = encode_attribute(value, attr.quote)?;
        self.apply_validated(
            span(info.open),
            attr.value.offset,
            attr.value.length,
            &encoded,
            false,
            true,
            "Edit attribute",
            node.slot,
            true,
        )
    }
    pub fn add_attribute(
        &mut self,
        node: DocumentHandle,
        name: &[u8],
        value: &[u8],
    ) -> Result<(), EditError> {
        checked_name(name)?;
        let encoded = encode_attribute(value, b'"')?;
        let cache = self.handle_index(node)?;
        let info = cache.node(node)?;
        if cache.attribute(info, name).is_some() {
            return Err(EditError::DuplicateAttribute);
        }
        let open = info
            .open
            .slice(&cache.source)
            .ok_or(EditError::InvalidOperation)?;
        let insert_at = start_tag_trailing_start(open);
        let size = name
            .len()
            .checked_add(encoded.len())
            .and_then(|n| n.checked_add(4))
            .ok_or(EditError::Limit)?;
        let mut patch = alloc::vector(size)?;
        patch.push(b' ');
        patch.extend_from_slice(name);
        patch.extend_from_slice(b"=\"");
        patch.extend_from_slice(&encoded);
        patch.push(b'"');
        self.apply_validated(
            span(info.open),
            info.open.offset + insert_at,
            0,
            &patch,
            false,
            true,
            "Add attribute",
            node.slot,
            false,
        )
    }
    pub fn remove_attribute(&mut self, node: DocumentHandle, name: &[u8]) -> Result<(), EditError> {
        let cache = self.handle_index(node)?;
        let info = cache.node(node)?;
        let attr = cache.attribute(info, name).ok_or(EditError::NotFound)?;
        // Attribute token source excludes its preceding whitespace. C retains it.
        self.apply_validated(
            span(info.open),
            attr.source.offset,
            attr.source.length,
            &[],
            false,
            true,
            "Remove attribute",
            node.slot,
            false,
        )
    }
    pub fn set_text_content(&mut self, node: DocumentHandle, text: &[u8]) -> Result<(), EditError> {
        let cache = self.handle_index(node)?;
        let info = cache.node(node)?;
        let encoded = encode_text(text)?;
        if info.empty {
            let name = info
                .name
                .slice(&cache.source)
                .ok_or(EditError::StaleHandle)?;
            let total = encoded
                .len()
                .checked_add(name.len())
                .and_then(|n| n.checked_add(4))
                .ok_or(EditError::Limit)?;
            let mut patch = alloc::vector(total)?;
            patch.push(b'>');
            patch.extend_from_slice(&encoded);
            patch.extend_from_slice(b"</");
            patch.extend_from_slice(name);
            patch.push(b'>');
            self.apply_validated(
                info.span,
                info.open.offset + info.open.length - 2,
                2,
                &patch,
                false,
                false,
                "Edit text",
                node.slot,
                false,
            )
        } else {
            let start = info.open.offset + info.open.length;
            self.apply_validated(
                info.span,
                start,
                info.close.offset - start,
                &encoded,
                false,
                false,
                "Edit text",
                node.slot,
                false,
            )
        }
    }
    pub fn delete_element(&mut self, node: DocumentHandle) -> Result<(), EditError> {
        let cache = self.handle_index(node)?;
        let info = cache.node(node)?;
        if cache.model.root() == Some(node) {
            return Err(EditError::RootDelete);
        }
        let parent = cache.model.parent(node).ok_or(EditError::StaleHandle)?;
        let region = cache.node(parent)?.span;
        self.apply_validated(
            region,
            info.span.offset,
            info.span.length,
            &[],
            false,
            false,
            "Delete",
            node.slot,
            false,
        )
    }
    pub fn duplicate_element(&mut self, node: DocumentHandle) -> Result<DocumentHandle, EditError> {
        let cache = self.handle_index(node)?;
        let info = cache.node(node)?;
        if cache.model.root() == Some(node) {
            return Err(EditError::InvalidOperation);
        }
        let parent = cache.model.parent(node).ok_or(EditError::StaleHandle)?;
        let region = cache.node(parent)?.span;
        let copy = self.copy_range(info.span.offset, info.span.length)?;
        let offset = info.span.offset + info.span.length;
        // Duplication deliberately preserves every byte, including nested IDs.
        self.apply_returning(
            region,
            offset,
            0,
            &copy,
            false,
            "Duplicate",
            node.slot,
            offset,
        )
    }
    pub fn reorder_sibling(
        &mut self,
        node: DocumentHandle,
        target: DocumentHandle,
        before: bool,
    ) -> Result<(), EditError> {
        let cache = self.handle_index(node)?;
        let a = cache.node(node)?;
        let b = cache.node(target)?;
        let parent = cache
            .model
            .parent(node)
            .ok_or(EditError::InvalidOperation)?;
        if node.slot == target.slot || cache.model.parent(target) != Some(parent) {
            return Err(EditError::InvalidOperation);
        }
        let region = cache.node(parent)?.span;
        if if before {
            a.span.offset < b.span.offset
        } else {
            a.span.offset > b.span.offset
        } {
            return Ok(());
        }
        let start = a.span.offset.min(b.span.offset);
        let end = (a.span.offset + a.span.length).max(b.span.offset + b.span.length);
        let old = self.copy_range(start, end - start)?;
        let mut patch = alloc::vector(old.len())?;
        if a.span.offset < b.span.offset {
            let gap = b.span.offset - (a.span.offset + a.span.length);
            patch.extend_from_slice(&old[a.span.length..a.span.length + gap]);
            patch.extend_from_slice(&old[a.span.length + gap..]);
            patch.extend_from_slice(&old[..a.span.length]);
        } else {
            let gap = a.span.offset - (b.span.offset + b.span.length);
            patch.extend_from_slice(&old[b.span.length + gap..]);
            patch.extend_from_slice(&old[..b.span.length]);
            patch.extend_from_slice(&old[b.span.length..b.span.length + gap]);
        }
        self.apply_validated(
            region,
            start,
            old.len(),
            &patch,
            false,
            false,
            "Move",
            node.slot,
            false,
        )
    }
    pub fn wrap_in_group(&mut self, node: DocumentHandle) -> Result<DocumentHandle, EditError> {
        let cache = self.handle_index(node)?;
        let info = cache.node(node)?;
        if cache.model.root() == Some(node) {
            return Err(EditError::InvalidOperation);
        }
        let mut patch = alloc::vector(info.span.length.checked_add(7).ok_or(EditError::Limit)?)?;
        patch.extend_from_slice(b"<g>");
        patch.extend_from_slice(
            self.span_bytes(info.span)
                .ok_or(EditError::InvalidOperation)?,
        );
        patch.extend_from_slice(b"</g>");
        self.apply_returning(
            info.span,
            info.span.offset,
            info.span.length,
            &patch,
            false,
            "Group",
            node.slot,
            info.span.offset,
        )
    }
    pub fn ungroup(&mut self, group: DocumentHandle) -> Result<(), EditError> {
        let cache = self.handle_index(group)?;
        let info = cache.node(group)?;
        if info.name.slice(&cache.source) != Some(b"g") {
            return Err(EditError::InvalidOperation);
        }
        let start = if info.empty {
            info.span.offset + info.span.length - 2
        } else {
            info.open.offset + info.open.length
        };
        let end = if info.empty { start } else { info.close.offset };
        let inner = self.copy_range(start, end - start)?;
        let root = cache.model.root() == Some(group);
        let region = if root {
            SourceSpan {
                offset: 0,
                length: self.byte_len,
            }
        } else {
            cache
                .node(cache.model.parent(group).ok_or(EditError::StaleHandle)?)?
                .span
        };
        self.apply_validated(
            region,
            info.span.offset,
            info.span.length,
            &inner,
            !root,
            false,
            "Ungroup",
            group.slot,
            false,
        )
    }
    pub fn replace_source_span(
        &mut self,
        span: SourceSpan,
        replacement: &[u8],
    ) -> Result<(), EditError> {
        self.index().map_err(|_| EditError::InvalidOperation)?;
        if span.offset > self.byte_len || span.length > self.byte_len - span.offset {
            return Err(EditError::InvalidOperation);
        }
        if span.length > MAX_FRAGMENT_BYTES || replacement.len() > MAX_FRAGMENT_BYTES {
            return Err(EditError::Limit);
        }
        self.apply_validated(
            SourceSpan {
                offset: 0,
                length: self.byte_len,
            },
            span.offset,
            span.length,
            replacement,
            false,
            false,
            "Edit path",
            0,
            false,
        )
    }
    pub fn replace_xml_region(
        &mut self,
        parent: DocumentHandle,
        region: SourceSpan,
        replacement: &[u8],
    ) -> Result<(), EditError> {
        self.replace_xml_region_labeled(parent, region, replacement, HistoryAction::EditObjects)
    }
    pub fn replace_xml_region_labeled(
        &mut self,
        parent: DocumentHandle,
        region: SourceSpan,
        replacement: &[u8],
        action: HistoryAction,
    ) -> Result<(), EditError> {
        let info = self.handle_index(parent)?.node(parent)?;
        if region.offset < info.span.offset
            || region.offset - info.span.offset > info.span.length
            || region.length > info.span.length - (region.offset - info.span.offset)
        {
            return Err(EditError::InvalidOperation);
        }
        if region.length > MAX_FRAGMENT_BYTES || replacement.len() > MAX_FRAGMENT_BYTES {
            return Err(EditError::Limit);
        }
        self.apply_validated(
            info.span,
            region.offset,
            region.length,
            replacement,
            true,
            false,
            action.label(),
            parent.slot,
            false,
        )
    }
    #[allow(clippy::too_many_arguments)]
    pub(crate) fn apply_validated(
        &mut self,
        region: SourceSpan,
        offset: usize,
        remove: usize,
        insert: &[u8],
        fragment: bool,
        start_tag: bool,
        label: &'static str,
        target: u32,
        coalescible: bool,
    ) -> Result<(), EditError> {
        self.validate_replace(region, offset, remove, insert, fragment, start_tag)?;
        self.replace(offset, remove, insert, label, target, coalescible)
    }
    #[allow(clippy::too_many_arguments)]
    pub(crate) fn apply_returning(
        &mut self,
        region: SourceSpan,
        offset: usize,
        remove: usize,
        insert: &[u8],
        fragment: bool,
        label: &'static str,
        target: u32,
        returned_offset: usize,
    ) -> Result<DocumentHandle, EditError> {
        self.validate_replace(region, offset, remove, insert, fragment, false)?;
        let cache = self.prepared_cache(offset, remove, insert)?;
        let handle =
            handle_at_offset(&cache, returned_offset).ok_or(EditError::InvalidOperation)?;
        self.publish_with_cache(offset, remove, insert, label, target, cache)?;
        Ok(handle)
    }
}
pub(crate) fn handle_at_offset(cache: &Cache, offset: usize) -> Option<DocumentHandle> {
    let mut best = None;
    for (slot, node) in cache.nodes.iter().enumerate() {
        if offset < node.span.offset || offset - node.span.offset >= node.span.length {
            continue;
        }
        let handle = cache.model.node_at(slot)?;
        let depth = cache.model.depth(handle)?;
        if best.is_none_or(|(d, _)| depth > d) {
            best = Some((depth, handle));
        }
    }
    best.map(|(_, h)| h)
}
pub(crate) fn span(s: vexel_xml::XmlSpan) -> SourceSpan {
    SourceSpan {
        offset: s.offset,
        length: s.length,
    }
}
pub(crate) fn start_tag_trailing_start(bytes: &[u8]) -> usize {
    if bytes.len() < 2 || bytes.last() != Some(&b'>') {
        return bytes.len();
    }
    let mut at = bytes.len() - 1;
    if at > 0 && bytes[at - 1] == b'/' {
        at -= 1;
    }
    while at > 0 && matches!(bytes[at - 1], b' ' | b'\t' | b'\r' | b'\n') {
        at -= 1;
    }
    at
}
pub fn name_valid(name: &[u8]) -> bool {
    checked_name(name).is_ok()
}
pub(crate) fn checked_name(name: &[u8]) -> Result<(), EditError> {
    if name.is_empty() || name.len() > 4096 {
        return Err(EditError::InvalidName);
    }
    let mut probe = alloc::vector(name.len().checked_add(13).ok_or(EditError::Limit)?)?;
    probe.extend_from_slice(b"<probe ");
    probe.extend_from_slice(name);
    probe.extend_from_slice(b"=\"x\"/>");
    crate::cache::parse_tokens(&probe)
        .map(|_| ())
        .map_err(|(e, _)| {
            if e == EditError::OutOfMemory {
                e
            } else {
                EditError::InvalidName
            }
        })
}
pub fn encode_attribute(input: &[u8], quote: u8) -> Result<Vec<u8>, EditError> {
    if !matches!(quote, b'\'' | b'"') {
        return Err(EditError::InvalidArgument);
    }
    encode(input, quote, false)
}
pub fn encode_text(input: &[u8]) -> Result<Vec<u8>, EditError> {
    encode(input, 0, true)
}
fn encode(input: &[u8], quote: u8, text: bool) -> Result<Vec<u8>, EditError> {
    let capacity = input
        .len()
        .checked_mul(6)
        .and_then(|n| n.checked_add(1))
        .ok_or(EditError::OutOfMemory)?;
    let mut out = alloc::vector(if input.is_empty() { 0 } else { capacity })?;
    for &b in input {
        let replacement: &[u8] = match b {
            b'&' => b"&amp;",
            b'<' => b"&lt;",
            b'>' if text => b"&gt;",
            b'\'' if !text && quote == b'\'' => b"&apos;",
            b'"' if !text && quote == b'"' => b"&quot;",
            _ => {
                out.push(b);
                continue;
            }
        };
        out.extend_from_slice(replacement);
    }
    Ok(out)
}

#include "document_edit.h"
