        (base_bytes){fragment, sizeof(fragment) - 1U}, &inserted) == DOCUMENT_EDIT_OK);
    base_bytes tag;
    CHECK(document_edit_tag_name(edit, inserted, &tag) && tag.len == 1U && tag.ptr[0] == 'g');
    CHECK(find_id(edit, "nested", &nested));
