    CHECK(created.error == DOCUMENT_EDIT_OK && created.edit != NULL);
    document_edit *edit = created.edit;
    for (uint8_t value = '1'; value <= '3'; ++value) {
        CHECK(document_edit_validate_replace(edit, 5U, 13U, 14U, 1U,
            &value, 1U, false, true));
